// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/// @title MultiSigVault - A multi-signature vault for secure fund management
/// @notice Requires k-of-n signatures for withdrawals above threshold
/// @dev Uses EIP-191 signed messages for off-chain signature collection
contract MultiSigVault {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct Proposal {
        address payable recipient;
        uint256 amount;
        string memo;
        uint256 deadline;
        bool executed;
        uint256 approvalCount;
    }

    address public owner;
    mapping(address => bool) public isSigner;
    address[] public signers;
    uint256 public requiredSignatures;
    uint256 public proposalCount;
    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) public hasApproved;
    mapping(bytes32 => bool) public usedHashes;

    uint256 public constant INSTANT_THRESHOLD = 1 ether;
    uint256 public nonce;

    event ProposalCreated(uint256 indexed id, address recipient, uint256 amount);
    event ProposalExecuted(uint256 indexed id);
    event SignerAdded(address indexed signer);
    event SignerRemoved(address indexed signer);
    event InstantTransfer(address indexed to, uint256 amount, string memo);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlySigner() {
        require(isSigner[msg.sender], "Not signer");
        _;
    }

    constructor(address[] memory _signers, uint256 _required) payable {
        require(_signers.length >= _required, "Invalid threshold");
        require(_required > 0, "Need at least 1");
        owner = msg.sender;
        for (uint256 i = 0; i < _signers.length; i++) {
            require(_signers[i] != address(0), "Zero address");
            require(!isSigner[_signers[i]], "Duplicate signer");
            isSigner[_signers[i]] = true;
            signers.push(_signers[i]);
        }
        requiredSignatures = _required;
    }

    receive() external payable {}

    /// @notice Create a proposal for large withdrawals
    function createProposal(
        address payable _recipient,
        uint256 _amount,
        string calldata _memo,
        uint256 _deadline
    ) external onlySigner returns (uint256) {
        require(_amount > 0, "Zero amount");
        require(_deadline > block.timestamp, "Past deadline");
        require(_recipient != address(0), "Zero recipient");

        uint256 id = proposalCount++;
        proposals[id] = Proposal({
            recipient: _recipient,
            amount: _amount,
            memo: _memo,
            deadline: _deadline,
            executed: false,
            approvalCount: 0
        });

        emit ProposalCreated(id, _recipient, _amount);
        return id;
    }

    /// @notice Approve a proposal
    function approveProposal(uint256 _id) external onlySigner {
        Proposal storage p = proposals[_id];
        require(!p.executed, "Already executed");
        require(block.timestamp <= p.deadline, "Expired");
        require(!hasApproved[_id][msg.sender], "Already approved");

        hasApproved[_id][msg.sender] = true;
        p.approvalCount++;
    }

    /// @notice Execute an approved proposal
    function executeProposal(uint256 _id) external onlySigner {
        Proposal storage p = proposals[_id];
        require(!p.executed, "Already executed");
        require(p.approvalCount >= requiredSignatures, "Not enough approvals");
        require(block.timestamp <= p.deadline, "Expired");
        require(address(this).balance >= p.amount, "Insufficient balance");

        p.executed = true;
        (bool success, ) = p.recipient.call{value: p.amount}("");
        require(success, "Transfer failed");

        emit ProposalExecuted(_id);
    }

    /// @notice Instant transfer for small amounts with collected signatures
    /// @dev For amounts <= INSTANT_THRESHOLD, allows immediate execution
    ///      with off-chain collected signatures to save gas on multi-tx approval
    /// @param _to Recipient address
    /// @param _amount Transfer amount (must be <= INSTANT_THRESHOLD)
    /// @param _memo Human-readable memo for the transfer
    /// @param _signatures Concatenated signatures from required signers
    function instantTransfer(
        address payable _to,
        uint256 _amount,
        string calldata _memo,
        bytes calldata _signatures
    ) external onlySigner {
        require(_amount <= INSTANT_THRESHOLD, "Above threshold");
        require(_amount > 0, "Zero amount");
        require(_to != address(0), "Zero address");
        require(address(this).balance >= _amount, "Insufficient balance");
        require(_signatures.length >= requiredSignatures * 65, "Not enough sigs");

        // Build the message hash for signature verification
        bytes32 messageHash = _buildMessageHash(_to, _amount, _memo);
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();

        // Verify we haven't used this exact message before (replay protection)
        require(!usedHashes[ethSignedHash], "Hash already used");
        usedHashes[ethSignedHash] = true;

        // Verify signatures
        uint256 validSigs = 0;
        address lastSigner = address(0);

        for (uint256 i = 0; i < requiredSignatures; i++) {
            bytes memory sig = _signatures[i * 65:(i + 1) * 65];
            address recovered = ethSignedHash.recover(sig);

            // Ensure signers are in ascending order (no duplicates)
            require(recovered > lastSigner, "Invalid signer order");
            require(isSigner[recovered], "Not a valid signer");
            lastSigner = recovered;
            validSigs++;
        }

        require(validSigs >= requiredSignatures, "Insufficient valid signatures");
        nonce++;

        (bool success, ) = _to.call{value: _amount}("");
        require(success, "Transfer failed");

        emit InstantTransfer(_to, _amount, _memo);
    }

    /// @dev Builds a unique message hash for signature verification
    /// @notice Uses encodePacked for gas efficiency in instant transfers
    ///         The nonce and chain ID prevent cross-chain and replay attacks
    function _buildMessageHash(
        address _to,
        uint256 _amount,
        string calldata _memo
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                address(this),
                _to,
                _amount,
                _memo,
                nonce,
                block.chainid
            )
        );
    }

    /// @notice Add a new signer (owner only)
    function addSigner(address _signer) external onlyOwner {
        require(_signer != address(0), "Zero address");
        require(!isSigner[_signer], "Already signer");
        isSigner[_signer] = true;
        signers.push(_signer);
        emit SignerAdded(_signer);
    }

    /// @notice Remove a signer (owner only)
    function removeSigner(address _signer) external onlyOwner {
        require(isSigner[_signer], "Not signer");
        require(signers.length > requiredSignatures, "Would break threshold");
        isSigner[_signer] = false;
        for (uint256 i = 0; i < signers.length; i++) {
            if (signers[i] == _signer) {
                signers[i] = signers[signers.length - 1];
                signers.pop();
                break;
            }
        }
        emit SignerRemoved(_signer);
    }

    /// @notice Update required signatures (owner only)
    function setRequiredSignatures(uint256 _required) external onlyOwner {
        require(_required > 0 && _required <= signers.length, "Invalid threshold");
        requiredSignatures = _required;
    }

    /// @notice Get vault balance
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}
